    if (!/\.[a-z0-9]+$/i.test(path) && file.url) {
      try { path = new URL(file.url).pathname; } catch { /* Keep the visible filename. */ }
    }
    if (unsupportedExtensions.test(path)) return { supported: false, reason: 'Formato no soportado' };
